package za.co.innaesim.backup.model;

import java.util.ArrayList;
import java.util.List;

import lombok.Data;

/**
 * A named backup job: what to back up, when, where to send it and how long to keep it.
 *
 * Getters and setters are generated by Lombok, so they don't appear in this documentation.
 */
@Data
public class JobConfig {
    private String name;
    private AppConfig database = new AppConfig();
    /** Five-field cron expression, or null when the job only runs on demand. */
    private String schedule;
    private List<String> destinations = new ArrayList<>();
    private RetentionConfig retention;

    /** Creates an empty job. */
    public JobConfig() {}
}
